        // `enforce_agent_kind` gate passes and the test reaches the
        // `VacSessionUnknown` branch under exam.
        std::fs::write(
            profile_root.path().join("assessor.yaml"),
            "id: assessor\nclass: assessor\nversion: 0.0.0\nallowed_agent_kinds:\n  - acp\n",
        )
        .unwrap();
